<?php
declare(strict_types=1);
require_once __DIR__ . '/FinanceiroCorporativoBaseService.php';
final class NegociacaoService extends FinanceiroCorporativoBaseService
{
 public static function criarComConexaoOficial():self{return new self(conectar());}
 public function criar(array $d,array $cobrancas):array{return $this->executarSeguro('Falha ao criar negociação','negociacoes',null,function()use($d,$cobrancas){if(!$cobrancas)throw new FinanceiroCorporativoException('Informe cobranças.','VALIDACAO_FALHOU');$eid=FinanceiroCorporativoValidator::inteiroPositivo($d['escritorio_id']??null,'escritorio_id');$e=$this->escritorio($eid);$desc=FinanceiroCorporativoValidator::dinheiro($d['valor_desconto']??'0','valor_desconto');$juros=FinanceiroCorporativoValidator::dinheiro($d['valor_juros']??'0','valor_juros');$parcelas=FinanceiroCorporativoValidator::inteiroPositivo($d['quantidade_parcelas']??1,'quantidade_parcelas');$venc=FinanceiroCorporativoValidator::dataOpcional($d['primeiro_vencimento_em']??null,'primeiro_vencimento_em');$per=FinanceiroCorporativoValidator::enum($d['periodicidade_parcelas']??'mensal','periodicidade_parcelas',['mensal','quinzenal','semanal','unica']);$termos=FinanceiroCorporativoValidator::textoOpcional($d['termos']??null,65000);$codigo=FinanceiroCorporativoCodigo::gerar('NEG');$uid=$this->usuarioIdAtual();$res=FinanceiroCorporativoTransaction::executar($this->conn,function()use($cobrancas,$eid,$e,$desc,$juros,$parcelas,$venc,$per,$termos,$codigo,$uid){$original='0.00';$rows=[];foreach($cobrancas as $cid){$cid=FinanceiroCorporativoValidator::inteiroPositivo($cid,'cobranca_id');$c=$this->buscarUm('SELECT * FROM saas_financeiro_cobrancas WHERE id=? FOR UPDATE','i',[$cid]);if(!$c||(int)$c['escritorio_id']!==$eid)throw new FinanceiroCorporativoException('Cobrança inválida.','COBRANCA_INVALIDA');if(in_array($c['status'],['cancelada','estornada','paga'],true))throw new FinanceiroCorporativoException('Cobrança não negociável.','STATUS_INVALIDO');$original=FinanceiroCorporativoValidator::somarDinheiro($original,$c['saldo_aberto']);$rows[]=$c;}if(FinanceiroCorporativoValidator::compararDinheiro($desc,$original)>0)throw new FinanceiroCorporativoException('Desconto superior ao saldo.','VALIDACAO_FALHOU');$neg=FinanceiroCorporativoValidator::somarDinheiro(FinanceiroCorporativoValidator::subtrairDinheiro($original,$desc),$juros);$s=$this->conn->prepare("INSERT INTO saas_financeiro_negociacoes (codigo,escritorio_id,tenant_id,status,tipo,valor_original,valor_desconto,valor_juros,valor_negociado,quantidade_parcelas,primeiro_vencimento_em,periodicidade_parcelas,termos,solicitada_em,criado_por) VALUES (?,?,?,'rascunho','acordo',?,?,?,?,?,?,?,?,NOW(),?)");$s->bind_param('sisssssissssi',$codigo,$e['id'],$e['tenant_id'],$original,$desc,$juros,$neg,$parcelas,$venc,$per,$termos,$uid);$s->execute();$nid=(int)$this->conn->insert_id;$s->close();foreach($rows as $c){$x=$this->conn->prepare('INSERT INTO saas_financeiro_negociacao_cobrancas (negociacao_id,cobranca_id,valor_incluido,saldo_anterior,status_anterior) VALUES (?,?,?,?,?)');$x->bind_param('iisss',$nid,$c['id'],$c['saldo_aberto'],$c['saldo_aberto'],$c['status']);$x->execute();$x->close();}$this->log->registrarStatus('negociacao',$nid,$eid,$e['tenant_id'],null,'rascunho','Negociação criada.');return $this->entidadePorCodigo('saas_financeiro_negociacoes',$codigo);});return $this->sucesso('Negociação criada.','NEGOCIACAO_CRIADA',$res);});}
 public function aprovar(string $codigo):array{return $this->status($codigo,['rascunho','solicitada'],'aprovada','NEGOCIACAO_APROVADA');}
 public function rejeitar(string $codigo,string $motivo):array{return $this->status($codigo,['rascunho','solicitada'],'rejeitada','NEGOCIACAO_REJEITADA',$motivo);}
 public function cancelar(string $codigo,string $motivo):array{return $this->status($codigo,['rascunho','solicitada','aprovada'],'cancelada','NEGOCIACAO_CANCELADA',$motivo);}
 private function status(string $codigo,array $permitidos,string $novo,string $ret,string $motivo=''):array{return $this->executarSeguro('Falha ao atualizar negociação','negociacoes',$codigo,function()use($codigo,$permitidos,$novo,$ret,$motivo){$n=$this->entidadePorCodigo('saas_financeiro_negociacoes',$codigo);if(!in_array($n['status'],$permitidos,true))throw new FinanceiroCorporativoException('Status inválido.','STATUS_INVALIDO');$uid=$this->usuarioIdAtual();$campo=$novo==='aprovada'?'aprovada_em':($novo==='cancelada'?'cancelada_em':null);$sql='UPDATE saas_financeiro_negociacoes SET status=?';$t='s';$p=[$novo];if($campo){$sql.=",$campo=NOW()";}if($novo==='aprovada'){$sql.=',aprovado_por=?';$t.='i';$p[]=$uid;}if($novo==='cancelada'){$sql.=',cancelado_por=?,motivo_cancelamento=?';$t.='is';$p[]=$uid;$p[]=$motivo;}$sql.=' WHERE id=?';$t.='i';$p[]=$n['id'];$s=$this->conn->prepare($sql);$s->bind_param($t,...$p);$s->execute();$s->close();$this->log->registrarStatus('negociacao',(int)$n['id'],(int)$n['escritorio_id'],$n['tenant_id'],$n['status'],$novo,$motivo);return $this->sucesso('Negociação atualizada.',$ret,$this->entidadePorCodigo('saas_financeiro_negociacoes',$codigo));});}
}
